            return new_dict
        if isinstance(value, list):
            new_list = []
            for item in value:
                processed_item = process(item, collected)
                if processed_item is not None:
                    new_list.append(processed_item)
            return new_list
        if isinstance(value, str) and is_email(value):
            collected.append(REPLACE_NONE)
            return REPLACE_NONE
        collected.append(value)
        return value

    try:
