import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    current = data
    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key '{key}' not found in JSON data")
    numeric_values = []
    def add_numeric(value):
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            numeric_values.append(float(value))
    if isinstance(current, (list, tuple, np.ndarray, set)):
        for item in current:
            add_numeric(item)
    elif isinstance(current, (int, float)) and not isinstance(current, bool):
        add_numeric(current)
    elif isinstance(current, str):
        s = current.strip()
        if not s:
            raise ValueError("Data string is empty")
        try:
            add_numeric(float(s))
        except ValueError:
            separators = [",", ";", "|", " "]
            replaced = s
            for sep in separators[1:]:
                replaced = replaced.replace(sep, separators[0])
            parts = [p for p in replaced.split(separators[0]) if p]
            if not parts:
                raise ValueError("No numeric data found in string")
            for p in parts:
                try:
                    add_numeric(float(p))
                except ValueError:
                    raise ValueError("Data string is corrupted or non-numeric")
    else:
        raise ValueError("No numeric data found at the specified path")
    if not numeric_values:
        raise ValueError("No numeric data found")
    arr = np.array(numeric_values, dtype=float)
    df = pd.DataFrame({"values": arr})
    fig, ax = plt.subplots()
    sns.boxplot(data=df, y="values", ax=ax)
    ax.set_title("Boxplot of Extracted Numeric Data")
    return fig
