import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except Exception:
        raise ValueError("Malformed JSON data")
    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("JSON data must be a non-empty list")
    countries = []
    populations = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each entry must be a dictionary")
        if "Country" not in item or "Population" not in item:
            raise ValueError("Each entry must contain 'Country' and 'Population' keys")
        country = item["Country"]
        population = item["Population"]
        if not isinstance(country, str):
            raise ValueError("Country names must be strings")
        if isinstance(population, bool):
            raise ValueError("Population must be numeric and non-negative")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric and non-negative")
        if population < 0:
            raise ValueError("Population cannot be negative")
        population_int = math.floor(population)
        countries.append(country)
        populations.append(population_int)
    df = pd.DataFrame({"Country": countries, "Population": populations})
    if not os.path.isdir(output_dir):
        try:
            os.makedirs(output_dir, exist_ok=True)
        except Exception as e:
            raise IOError(f"Cannot create directory: {e}")
    output_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(output_path, index=False)
    except Exception as e:
        raise IOError(f"Failed to write CSV file: {e}")
    return output_path, df
